const tideLeapfishSheet=new Image();tideLeapfishSheet.assetSrc='assets/tide-leapfish-v2.png';
function beginTideLeapfish(e){let dx=p.x-e.x,dy=p.y-e.y,len=Math.hypot(dx,dy),reach=Math.min(420,len+100),origin={x:e.x,y:e.y},end={...origin};for(let s=6;s<reach+6;s+=6){let d=Math.min(s,reach),q={x:e.x+dx/(len||1)*d,y:e.y+dy/(len||1)*d};if(!passable(q.x,q.y,18)||!lineClear(end,q,18))break;end=q;}e.state='attack';e.elapsed=0;e.struck=false;e.facing=dx-dy<0?-1:1;e.attack={pattern:'tideBombLeap',bespoke:true,windup:2,origin,end,last:{...origin},landed:false,crashed:false,crashAt:null,pulses:0,marks:[1/3,2/3,1].map(t=>({x:origin.x+(end.x-origin.x)*t,y:origin.y+(end.y-origin.y)*t}))};}
const tideLeapfishAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r8e5')return tideLeapfishAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='tideBombLeap'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=400&&clear){beginTideLeapfish(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.65;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,108*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.last)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.crashed&&!a.landed&&e.elapsed>=.85){let t=e.elapsed>=1.4?1:Math.max(0,(e.elapsed-.85)/.55),q={x:a.origin.x+(a.end.x-a.origin.x)*t,y:a.origin.y+(a.end.y-a.origin.y)*t},dx=q.x-e.x,dy=q.y-e.y,n=Math.max(1,Math.ceil(Math.hypot(dx,dy)/6));for(let j=0;j<n;j++){let x=e.x+dx/n,y=e.y+dy/n;if(!passable(x,y,18)||!lineClear(e,{x,y},18)){a.crashed=true;a.crashAt=e.elapsed;break;}e.x=x;e.y=y;}a.last={x:e.x,y:e.y};if(!a.crashed&&t===1){a.landed=true;e.struck=true;burst(e.x,e.y,50,'#8bd8ef');playSound('impact',e.x,e.y);}}
 if(!a.crashed&&a.landed){while(a.pulses<3&&e.elapsed>=1.4+a.pulses*.3-1e-8){let mark=a.marks[a.pulses++];if(lineClear(e,mark)&&dist(mark,p)<=70+1e-8&&lineClear(mark,p))hurt(60);burst(mark.x,mark.y,70,'#8bd8ef');playSound('impact',mark.x,mark.y);}}
 if(a.crashed?e.elapsed>=a.crashAt+1.2:e.elapsed>=3.2){e.attack=null;e.state='idle';e.t=2.6;}
};
function tideLeapfishLift(e){let a=e.attack;return e.hp>0&&a?.pattern==='tideBombLeap'&&!a.crashed&&!a.landed&&e.elapsed>.85?Math.sin(Math.PI*Math.max(0,Math.min(1,(e.elapsed-.85)/.55)))*100:e.hp>0&&e.state==='walk'?Math.abs(Math.sin((e.anim||0)*9))*14:0;}
const tideLeapfishDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r8e5'||!tideLeapfishSheet.complete||!tideLeapfishSheet.naturalWidth||!tideLeapfishSheet.naturalHeight)return tideLeapfishDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='tideBombLeap')f={row:2,col:e.attack.crashed?3:e.elapsed<.85?0:e.elapsed<1.4?1:e.elapsed<1.7?2:3};let q=project(e.x,e.y),sw=tideLeapfishSheet.naturalWidth/4,sh=tideLeapfishSheet.naturalHeight/3,w=260,h=w*sh/sw,anchor=[.81,.84,.82][f.row];ctx.save();ctx.translate(q.x,q.y-tideLeapfishLift(e));ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,tideLeapfishSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(tideLeapfishSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const tideLeapfishSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r8e5'?165:tideLeapfishSizeBase(e);
const tideLeapfishGroundBase=drawGroundEffects;drawGroundEffects=()=>{tideLeapfishGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r8e5'):enemies)){let a=e.attack;if(e.species!=='r8e5'||e.hp<=0||a?.pattern!=='tideBombLeap')continue;if(a.crashed||e.elapsed>=2.3){if(visibleAt(e.x,e.y))groundRing(e.x,e.y,30,'#9bddcf',2);continue;}for(let i=0;i<3;i++){let mark=a.marks[i],fired=i<a.pulses;if(fired&&e.elapsed>1.65+i*.3)continue;if(visibleAt(mark.x,mark.y)){groundRing(mark.x,mark.y,70,fired?'#d7f9ff':'#6ebbdc',fired?3:1);if(!fired)groundRing(mark.x,mark.y,10+i*7,'#a7e7f1',2);}}if(!a.landed){let q=project(a.origin.x,a.origin.y),r=project(a.end.x,a.end.y);ctx.save();ctx.strokeStyle='#8ed8eb55';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(r.x,r.y);ctx.stroke();ctx.restore();}}};
